from PIL import Image,ImageDraw,ImageFont
from pathlib import Path
root=Path('/work');im=Image.new('RGB',(1240,1754),'white');draw=ImageDraw.Draw(im);font=ImageFont.truetype('/fonts/LiberationSans-Regular.ttf',32);bold=ImageFont.truetype('/fonts/LiberationSans-Bold.ttf',44)
draw.text((90,75),'Quarterly Service Report',font=bold,fill='black')
lines=['Reporting period: January to March 2026','Prepared for: Operations and Service Quality','This report describes the results of a controlled service review.','The review covered service availability, response time, and customer support.','During the quarter the team completed 128 scheduled maintenance tasks.','The average response time was 12 minutes for priority requests.','A total of 96 customer inquiries were resolved within two working days.','The document was reviewed by the operations manager on April 10, 2026.','No critical service interruptions were recorded during the review period.','The team identified three opportunities to improve the reporting process.','First, standardize the collection of monthly service performance data.','Second, document the steps required to restore an interrupted workflow.','Third, review the capacity plan before adding new customer workloads.','All changes should be tested in an isolated environment before release.','The next review is scheduled for the first week of July 2026.','Contact: service-operations@example.org','Reference number: QSR-2026-0410','End of report.']
for i,line in enumerate(lines):draw.text((90,170+i*73),line,font=font,fill='black')
im.save(root/'sample.png');(root/'expected.txt').write_text('\n'.join(['Quarterly Service Report','128 scheduled maintenance tasks','12 minutes','QSR-2026-0410']))
